"""Emission compliance tests for backend (auto-generated by pact)."""

from backend.backend import Backend


class TestEmissionCompliance:
    """Verify backend emits structured events correctly."""

    def _make_handler(self):
        events = []
        return events, lambda event: events.append(event)

    def test_health_check_emits_events(self):
        """Method health_check emits invoked and completed events."""
        events, handler = self._make_handler()
        obj = Backend(event_handler=handler)
        try:
            obj.health_check()
        except (TypeError, Exception):
            pass
        invoked = [e for e in events if e.get("event") == "invoked"]
        completed = [e for e in events if e.get("event") in ("completed", "error")]
        assert len(invoked) >= 1, 'No invoked event for health_check'
        assert len(completed) >= 1, 'No completed/error event for health_check'
        assert invoked[0].get("pact_key") == "PACT:backend:health_check"
        assert isinstance(invoked[0].get("input_classification"), list)

