    def test_pact_key_format(self):
        """All emitted events have correctly formatted PACT keys."""
        events, handler = self._make_handler()
        obj = Backend(event_handler=handler)
        try:
            obj.health_check()
        except (TypeError, Exception):
            pass
        try:
            obj.list_tasks()
        except (TypeError, Exception):
            pass
        try:
            obj.create_task()
        except (TypeError, Exception):
            pass
        try:
            obj.get_task()
        except (TypeError, Exception):
            pass
        try:
            obj.update_task()
        except (TypeError, Exception):
            pass
        try:
            obj.delete_task()
        except (TypeError, Exception):
            pass
        try:
            obj.init_connection_pool()
        except (TypeError, Exception):
            pass
        try:
            obj.close_connection_pool()
        except (TypeError, Exception):
            pass
        try:
            obj.get_connection()
        except (TypeError, Exception):
            pass
        try:
            obj.db_list_tasks()
        except (TypeError, Exception):
            pass
        try:
            obj.db_create_task()
        except (TypeError, Exception):
            pass
        try:
            obj.db_get_task()
        except (TypeError, Exception):
            pass
        try:
            obj.db_update_task()
        except (TypeError, Exception):
            pass
        try:
            obj.db_delete_task()
        except (TypeError, Exception):
            pass
        for event in events:
            key = event.get("pact_key", "")
            assert key.startswith("PACT:backend:"), f"Bad pact_key: {key}"

